create extension if not exists pgcrypto;

create table if not exists public.angelcare_marketplace_public_inquiries(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PUB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),audience text not null,source_route text not null,full_name text not null,email text,phone text,organization text,city text,message text not null,consent_granted_at timestamptz not null,locale text not null default 'fr' check(locale in('fr','en','ar')),territory_id uuid,status text not null default 'new' check(status in('new','triaged','in_progress','qualified','closed','spam')),owner_id uuid,request_fingerprint text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_public_events(id uuid primary key default gen_random_uuid(),event_name text not null,route text not null,locale text not null default 'fr',territory_id uuid,inquiry_id uuid references public.angelcare_marketplace_public_inquiries(id) on delete set null,event_data jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists angelcare_marketplace_public_inquiries_status_idx on public.angelcare_marketplace_public_inquiries(status,created_at desc);
create index if not exists angelcare_marketplace_public_events_route_idx on public.angelcare_marketplace_public_events(route,event_name,created_at desc);

insert into public.angelcare_marketplace_cms_pages(route_key,locale,title,navigation_label,slug,description,status,translation_status,sensitive,seo_title,seo_description,canonical_url,owner_id,created_by,updated_by,published_at,published_version)
select 'public.home','fr','ANGELCARE · Un univers gouverné pour l’enfance et la famille','Accueil','accueil','Services, confiance, accompagnement familial et portes d’entrée partenaires.','published','source',false,'ANGELCARE · Kids, Family & Partner Universe','Découvrez l’univers ANGELCARE pour les familles et les organisations.','/angelcare-marketplace/fr',null,null,null,now(),1
where not exists(select 1 from public.angelcare_marketplace_cms_pages where locale='fr' and slug='accueil' and territory_id is null);

insert into public.angelcare_marketplace_cms_blocks(page_id,block_key,block_type,sort_order,status,content,settings,audience,locale)
select p.id,'home-hero','hero',0,'active',jsonb_build_object('eyebrow','ANGELCARE BUILD 360','title','Un univers de confiance pour les enfants, les familles et leurs partenaires.','lead','Des parcours structurés, des preuves visibles et une coordination ANGELCARE gouvernée.','primaryCtaKey','family_start','primaryCtaLabel','Commencer en famille','secondaryCtaKey','contact','secondaryCtaLabel','Parler à ANGELCARE'),'{}','{public}','fr' from public.angelcare_marketplace_cms_pages p where p.locale='fr' and p.slug='accueil' and p.territory_id is null on conflict(page_id,block_key) do nothing;

insert into public.angelcare_marketplace_cms_menus(menu_key,name,locale,status) values('public-main-fr','Navigation publique FR','fr','published') on conflict(menu_key) do update set status='published',updated_at=now();
insert into public.angelcare_marketplace_cms_menu_items(menu_id,label,href,sort_order,visibility,status)
select m.id,x.label,x.href,x.sort_order,'public','active' from public.angelcare_marketplace_cms_menus m cross join (values('Accueil','/angelcare-marketplace/fr',0),('Familles','/angelcare-marketplace/fr/familles',10),('Établissements','/angelcare-marketplace/fr/etablissements',20),('Confiance','/angelcare-marketplace/fr/confiance',30)) as x(label,href,sort_order) where m.menu_key='public-main-fr' and not exists(select 1 from public.angelcare_marketplace_cms_menu_items i where i.menu_id=m.id and i.href=x.href);

create or replace view public.angelcare_marketplace_public_navigation_v as select i.id,i.menu_id,i.label,i.href,i.page_id,i.parent_id,i.sort_order,i.visibility,i.status,m.locale,m.territory_id from public.angelcare_marketplace_cms_menu_items i join public.angelcare_marketplace_cms_menus m on m.id=i.menu_id where i.status='active' and m.status='published';

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values('marketplace.public.inquiries.view','Voir les entrées publiques','Public Universe',false),('marketplace.public.inquiries.manage','Gérer les entrées publiques','Public Universe',true),('marketplace.public.inquiries.export','Exporter les entrées publiques','Public Universe',true),('marketplace.public.analytics.view','Voir l’analytique publique','Public Universe',false),('marketplace.public.content.preview','Prévisualiser le public','Public Universe',false) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive','marketplace_product_admin') and p.permission_key like 'marketplace.public.%' on conflict do nothing;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.public-universe.enabled','Univers public global','Homepage, routes audiences, Trust, Marketplace, Partner OS et Academy.',true,'active','Ultra Delivery 1/5') on conflict(flag_key) do update set enabled=true,status='active',updated_at=now();

alter table public.angelcare_marketplace_public_inquiries enable row level security;alter table public.angelcare_marketplace_public_events enable row level security;
revoke all on table public.angelcare_marketplace_public_inquiries,public.angelcare_marketplace_public_events from anon,authenticated;
grant all on table public.angelcare_marketplace_public_inquiries,public.angelcare_marketplace_public_events to service_role;
